{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "value",
      "type": "string",
      "required": true,
      "description": "The value this item represents within its group. The group's value matches against this to determine the checked state."
    },
    {
      "name": "label",
      "type": "ReactNode",
      "required": true,
      "description": "Primary label text identifying the option."
    },
    {
      "name": "description",
      "type": "ReactNode",
      "description": "Secondary description text displayed below the label."
    },
    {
      "name": "icon",
      "type": "IconType",
      "description": "Icon to display before the label. See `astryx docs icons` for valid semantic names."
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "default": "false",
      "description": "Whether this individual radio item is disabled. A disabled item stays in the accessibility tree as disabled (aria-disabled), and the arrow keys and typeahead reach it so keyboard users find it. The pointer highlight skips it, and selection is blocked."
    },
    {
      "name": "endContent",
      "type": "ReactNode",
      "description": "Content to render after the label and description, such as a badge or metadata."
    },
    {
      "name": "ref",
      "type": "React.Ref<HTMLElement>",
      "description": "Ref forwarded to the row root, the element carrying role=\"menuitemradio\". Register the row with an element-keyed observer or overlay."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
